create table if not exists otp_challenges (id uuid primary key default gen_random_uuid(), employee_id text not null, email text not null, otp_hash text not null, expires_at timestamptz not null, attempts integer not null default 0, consumed_at timestamptz, created_at timestamptz not null default now()); create index if not exists idx_otp_challenges_employee on otp_challenges(employee_id,created_at desc); create index if not exists idx_otp_challenges_expires on otp_challenges(expires_at);
